#define C(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA:%s line%d\n",cudaGetErrorString(e),__LINE__);exit(7);}}while(0)
template<class T>std::vector<T>rd(std::string name,int n){std::ifstream f(name,std::ios::binary);std::vector<T>a(n);f.read((char*)a.data(),n*sizeof(T));if(!f||f.peek()!=EOF)exit(2);return a;}
int main(){for(int k=0;k<5;k++){int w=WS[k],h=HS[k],kw=KWS[k],kh=KHS[k],n=NS[k];auto image=rd<unsigned char>("image"+std::to_string(k)+".bin",3*w*h);auto kernel=rd<unsigned char>("kernel"+std::to_string(k)+".bin",3*kw*kh);unsigned char *di,*dk;int *ds,*dm,*dc;C(cudaMalloc(&di,image.size()));C(cudaMalloc(&dk,kernel.size()));C(cudaMalloc(&ds,(n+32)*4));C(cudaMalloc(&dm,4));C(cudaMalloc(&dc,4));C(cudaMemcpy(di,image.data(),image.size(),cudaMemcpyHostToDevice));C(cudaMemcpy(dk,kernel.data(),kernel.size(),cudaMemcpyHostToDevice));for(int corrected=0;corrected<2;corrected++){std::vector<int>capture(n+32,-99999);C(cudaMemcpy(ds,capture.data(),capture.size()*4,cudaMemcpyHostToDevice));int m=20,c=0;C(cudaMemcpy(dm,&m,4,cudaMemcpyHostToDevice));C(cudaMemcpy(dc,&c,4,cudaMemcpyHostToDevice));dim3 grid((w+15)/16,(h+15)/16);if(corrected)compute_sad_array_corrected<<<grid,dim3(16,16)>>>(ds+16,di,dk,n,w,h,kw,kh,kw*kh);else compute_sad_array<<<grid,dim3(16,16)>>>(ds+16,di,dk,n,w,h,kw,kh,kw*kh);find_min_in_sad_array<<<(n+255)/256,256>>>(n,ds+16,dm);get_num_of_occurrences<<<(n+255)/256,256>>>(n,ds+16,dm,dc);C(cudaDeviceSynchronize());C(cudaGetLastError());C(cudaMemcpy(capture.data(),ds,capture.size()*4,cudaMemcpyDeviceToHost));C(cudaMemcpy(&m,dm,4,cudaMemcpyDeviceToHost));C(cudaMemcpy(&c,dc,4,cudaMemcpyDeviceToHost));auto oracle=rd<int>((corrected?"oracle":"original_oracle")+std::to_string(k)+".bin",n);int mismatch=0;for(int i=0;i<n;i++)mismatch+=capture[i+16]!=oracle[i];for(int i=0;i<16;i++)if(capture[i]!=-99999||capture[n+16+i]!=-99999)return 9;bool good=mismatch==0&&m==(corrected?MINS[k]:OMINS[k])&&c==(corrected?COUNTS[k]:OCOUNTS[k]);std::string path="native_diagnostics/"+std::string(corrected?"corrected":"original")+"_case"+std::to_string(k)+".bin";capture.push_back(m);capture.push_back(c);std::ofstream f(path,std::ios::binary);f.write((char*)capture.data(),capture.size()*4);f.close();printf("SAD_COORDINATE_PROBE case=%d corrected=%d fullfield_mismatches_to_independent_declared_semantics=%d min=%d count=%d pass=%d\n",k,corrected,mismatch,m,c,good);fflush(stdout);if(!good)return 4;}cudaFree(di);cudaFree(dk);cudaFree(ds);cudaFree(dm);cudaFree(dc);}return 0;}
